<?php
if(PHP_SAPI!=='cli'){http_response_code(403);exit;}
chdir(dirname(__DIR__));require 'app/Core/DB.php';$db=DB::getInstance();$plans=json_decode(file_get_contents($argv[1]??''),true,512,JSON_THROW_ON_ERROR);if(count($plans)!==51)throw new RuntimeException('Expected 51 consultancy packages');$prepared=[];
foreach($plans as $p){$id=(int)$p['id'];$h=$db->query("SELECT * FROM kontrak_neo WHERE id=? AND kd_wilayah='76.01' AND kd_opd='1.03.0.00.0.00.01.0000' AND tahun=2026 AND is_deleted=0",[$id])->fetch();if(!$h||$h['status_kontrak']!=='draft'||$h['kunci']||$h['setujui']||!str_starts_with($h['jenis_pengadaan'],'KONSULTANSI')||(float)$h['total_anggaran']>100000000)throw new RuntimeException('Contract changed or processed: '.$id);
 if(!is_file($p['file'])||hash_file('sha256',$p['file'])!==$p['sha256'])throw new RuntimeException('Excel changed after verification');
 $old=array_column($p['before_contract']['rab'],null,'id');$current=$db->query('SELECT * FROM rab_paket_neo WHERE kontrak_id=? AND is_deleted=0',[$id])->fetchAll();if(count($current)!==count($p['rows']))throw new RuntimeException('RAB structure changed');
 foreach($current as $r){if(!isset($old[$r['id']]))throw new RuntimeException('Unknown row');foreach(['uraian','satuan','vol_hps','harga_sat_hps','jumlah_hps','vol_penawaran','harga_sat_penawaran','jumlah_penawaran','vol_negoisasi','harga_sat_negoisasi','jumlah_negoisasi','pajak'] as $f)if((string)$r[$f]!== (string)$old[$r['id']][$f])throw new RuntimeException('RAB edited while preparing Excel: '.$id.' '.$f);}
 $sum=0;foreach($p['rows'] as $r){$calc=round((float)$r['volume']*(float)$r['price']*(1+(float)$r['pajak']/100),2);if(abs($calc-(float)$r['total'])>.001)throw new RuntimeException('Excel arithmetic mismatch');$sum+=$calc;}
 if(abs($sum-(float)$p['target'])>.001||$sum>=(float)$p['hps']||$sum>(float)$h['total_anggaran'])throw new RuntimeException('Offer total invalid');$prepared[]=[$p,$h];
}
$actor='VARIASI_PENAWARAN_EXCEL_2026';$report=[];$db->begin();try{foreach($prepared as [$p,$h]){
 foreach($p['rows'] as $r){$db->update('rab_paket_neo',['vol_penawaran'=>$r['volume'],'harga_sat_penawaran'=>$r['price'],'jumlah_penawaran'=>$r['total'],'vol_negoisasi'=>$r['volume'],'harga_sat_negoisasi'=>$r['price'],'jumlah_negoisasi'=>$r['total'],'bobot'=>round((float)$r['total']/(float)$p['target']*100,4),'keterangan'=>'Excel penawaran '.$p['rup'].'; variasi harga perusahaan dan paket; tanpa item pembulatan tambahan.','username_update'=>$actor,'tgl_update'=>date('Y-m-d H:i:s')],'WHERE id=? AND kontrak_id=?',[$r['id'],$h['id']]);}
 if($h['rekanan_id']){$items=$db->query('SELECT id FROM kontrak_item_neo WHERE kontrak_id=? AND is_deleted=0',[$h['id']])->fetchAll();if(count($items)!==1)throw new RuntimeException('Expected one linked budget item');$db->update('kontrak_item_neo',['nilai_kontrak'=>$p['target'],'username_update'=>$actor,'tgl_update'=>date('Y-m-d H:i:s')],'WHERE id=?',[$items[0]['id']]);$db->update('kontrak_neo',['nilai_hps'=>$p['hps'],'nilai_kontrak'=>$p['target'],'username_update'=>$actor,'tgl_update'=>date('Y-m-d H:i:s')],'WHERE id=?',[$h['id']]);}
 $check=$db->query('SELECT SUM(jumlah_penawaran) penawaran,SUM(jumlah_negoisasi) negosiasi FROM rab_paket_neo WHERE kontrak_id=? AND is_deleted=0',[$h['id']])->fetch();if(abs((float)$check['penawaran']-(float)$p['target'])>.001||abs((float)$check['negosiasi']-(float)$p['target'])>.001)throw new RuntimeException('Persisted total differs');$report[]=['id'=>(int)$h['id'],'company'=>$p['company'],'package'=>$p['package'],'hps'=>$p['hps'],'penawaran'=>$p['target'],'selisih'=>$p['discount'],'file'=>$p['file'],'sha256'=>$p['sha256'],'header_updated'=>(bool)$h['rekanan_id'],'status'=>'PASS'];
}$db->commit();}catch(Throwable $e){$db->rollback();throw $e;}
file_put_contents('outputs/konsultansi-perubahan-2026/verifikasi-database.json',json_encode($report,JSON_PRETTY_PRINT|JSON_UNESCAPED_UNICODE|JSON_UNESCAPED_SLASHES).PHP_EOL);echo json_encode(['packages'=>count($report),'rab_rows'=>array_sum(array_map(fn($p)=>count($p['rows']),$plans)),'headers_updated'=>count(array_filter($report,fn($p)=>$p['header_updated'])),'waiting_provider'=>array_column(array_filter($report,fn($p)=>!$p['header_updated']),'id'),'totals_match_excel'=>true]).PHP_EOL;
